<?php
declare(strict_types=1);
require __DIR__ . '/_bootstrap.php';

if ($currentRole !== 'superadmin') {
    http_response_code(403);
    admin_layout_start('Ride Results', 'events');
    echo '<div class="alert alert-danger">Ride results entry is currently available to Super Admins only.</div>';
    admin_layout_end();
    exit;
}

ensureRideResultsTables($pdo);
$eventId = max(0, (int)($_GET['event_id'] ?? $_POST['event_id'] ?? 0));
$event = $eventId ? fetchEventById($pdo, $eventId) : null;
if (!$event) { http_response_code(404); $alerts[]=['type'=>'danger','message'=>'Ride not found.']; }
$lastDate = $event ? (string)($event['end_date'] ?: $event['event_date']) : '';
if ($event && $lastDate >= date('Y-m-d')) $alerts[]=['type'=>'warning','message'=>'Results can only be recorded after the ride has finished.'];

if ($event && !$alerts && $_SERVER['REQUEST_METHOD'] === 'POST') {
    $action = (string)($_POST['action'] ?? '');
    if ($action === 'save_distances') {
        $rows = (array)($_POST['classes'] ?? []);
        $save = $pdo->prepare("INSERT INTO event_result_classes(event_id,class_code,class_label,class_group,actual_distance_km) VALUES(:event,:code,:label,:group,:distance) ON DUPLICATE KEY UPDATE class_label=VALUES(class_label),class_group=VALUES(class_group),actual_distance_km=VALUES(actual_distance_km)");
        foreach ($rows as $code => $row) {
            $distance = trim((string)($row['distance'] ?? ''));
            if ($distance === '' || !is_numeric($distance) || (float)$distance < 0 || (float)$distance > 999.99) { $alerts[]=['type'=>'danger','message'=>'Enter a valid actual distance for every class.']; break; }
            $save->execute([':event'=>$eventId,':code'=>(string)$code,':label'=>(string)($row['label'] ?? $code),':group'=>strtoupper((string)($row['group'] ?? 'OTHER')),':distance'=>(float)$distance]);
        }
        if (!$alerts) { $_SESSION['flash_success']='Class distances saved. You can now record competitor results.'; header('Location: event_results.php?event_id='.$eventId.'#results'); exit; }
    }
    if ($action === 'save_results') {
        $entries = rideResultEntries($pdo, $event);
        $byId=[]; foreach($entries as $entry) $byId[(int)$entry['id']]=$entry;
        $classes=[];
        $q=$pdo->prepare('SELECT class_code,actual_distance_km FROM event_result_classes WHERE event_id=:id'); $q->execute([':id'=>$eventId]); foreach($q->fetchAll() ?: [] as $class) $classes[$class['class_code']]=$class['actual_distance_km'];
        $allowed=['pending','completed','retired','eliminated','non_starter','withdrawn'];
        $save=$pdo->prepare("INSERT INTO ride_results(event_id,booking_item_id,person_id,horse_id,class_code,class_group,status,distance_km,started_at,finished_at,ready_for_vet_at,ride_minutes,vet_minutes,final_heart_rate,vet_result,notes,rider_mileage_eligible,horse_mileage_eligible,created_by_user_id,updated_by_user_id) VALUES(:event,:item,:person,:horse,:code,:group,:status,:distance,:start,:finish,:vet,:ride_minutes,:vet_minutes,:hr,:result,:notes,:member,:logbook,:user,:user) ON DUPLICATE KEY UPDATE status=VALUES(status),distance_km=VALUES(distance_km),started_at=VALUES(started_at),finished_at=VALUES(finished_at),ready_for_vet_at=VALUES(ready_for_vet_at),ride_minutes=VALUES(ride_minutes),vet_minutes=VALUES(vet_minutes),final_heart_rate=VALUES(final_heart_rate),vet_result=VALUES(vet_result),notes=VALUES(notes),rider_mileage_eligible=VALUES(rider_mileage_eligible),horse_mileage_eligible=VALUES(horse_mileage_eligible),updated_by_user_id=VALUES(updated_by_user_id)");
        foreach ((array)($_POST['results'] ?? []) as $itemId => $posted) {
            $entry=$byId[(int)$itemId] ?? null; if (!$entry) continue;
            $status=in_array(($posted['status'] ?? ''),$allowed,true) ? $posted['status'] : 'pending';
            $distance=trim((string)($posted['distance'] ?? '')); if($distance==='') $distance=(string)($classes[$entry['class_code']] ?? '');
            if($distance!=='' && (!is_numeric($distance)||(float)$distance<0||(float)$distance>999.99)) { $alerts[]=['type'=>'danger','message'=>'A distance is invalid for '.$entry['rider_name'].'.']; break; }
            $start=rideResultTime((string)$event['event_date'],(string)($posted['start'] ?? '')); $finish=rideResultTime((string)$event['event_date'],(string)($posted['finish'] ?? '')); $vet=rideResultTime((string)$event['event_date'],(string)($posted['vet'] ?? ''));
            if ((trim((string)($posted['start']??''))!==''&&!$start)||(trim((string)($posted['finish']??''))!==''&&!$finish)||(trim((string)($posted['vet']??''))!==''&&!$vet)) { $alerts[]=['type'=>'danger','message'=>'Use times in HH:MM format.']; break; }
            $rideMinutes=rideResultMinutes($start,$finish); $vetMinutes=rideResultMinutes($finish,$vet);
            if (($start&&$finish&&$rideMinutes===null)||($finish&&$vet&&$vetMinutes===null)) { $alerts[]=['type'=>'danger','message'=>'Finish and ready-for-vet times must be after the preceding time.']; break; }
            $hr=trim((string)($posted['hr']??'')); if($hr!==''&&(!ctype_digit($hr)||(int)$hr>300)){ $alerts[]=['type'=>'danger','message'=>'Final heart rate must be a whole number up to 300.']; break; }
            $result=in_array(($posted['vet_result']??''),['pass','fail'],true)?$posted['vet_result']:null;
            $save->execute([':event'=>$eventId,':item'=>(int)$entry['id'],':person'=>$entry['person_id']?:null,':horse'=>$entry['horse_id']?:null,':code'=>$entry['class_code'],':group'=>$entry['class_group'],':status'=>$status,':distance'=>$distance===''?null:(float)$distance,':start'=>$start,':finish'=>$finish,':vet'=>$vet,':ride_minutes'=>$rideMinutes,':vet_minutes'=>$vetMinutes,':hr'=>$hr===''?null:(int)$hr,':result'=>$result,':notes'=>trim((string)($posted['notes']??''))?:null,':member'=>$entry['member_eligible']?1:0,':logbook'=>$entry['logbook_eligible']?1:0,':user'=>(int)$currentUser['id']]);
        }
        if (!$alerts) { $_SESSION['flash_success']='Ride results saved.'; header('Location: event_results.php?event_id='.$eventId.'#results'); exit; }
    }
}

$entries=$event&&!$alerts?rideResultEntries($pdo,$event):[];
$classRows=[];
if($event){$saved=[];$q=$pdo->prepare('SELECT * FROM event_result_classes WHERE event_id=:id');$q->execute([':id'=>$eventId]);foreach($q->fetchAll()?:[] as $row)$saved[$row['class_code']]=$row;foreach($entries as $entry){$code=$entry['class_code'];if($code==='')continue;if(!isset($classRows[$code])){$planned='';if(preg_match('/(\d+(?:\.\d+)?)\s*km/i',$entry['class_label'],$match))$planned=$match[1];$classRows[$code]=['code'=>$code,'label'=>$entry['class_label'],'group'=>$entry['class_group'],'distance'=>$saved[$code]['actual_distance_km']??$planned];}}}
$distancesReady=$classRows && !array_filter($classRows,static fn($r)=>$r['distance']==='');
admin_layout_start($event ? 'Record Ride Results' : 'Ride Results','events');
?>
<div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3"><div><div class="small text-muted">Post-ride results</div><h5 class="mb-0"><?php echo $event?h($event['title']):'Ride not found'; ?></h5></div><a class="btn btn-outline-secondary" href="events.php?view=past">Back to past rides</a></div>
<?php if($event): ?>
<div class="card-soft p-4 mb-4"><h6>1. Confirm actual distance for each class</h6><p class="small text-muted">Start with the planned route distance, then amend it where the route ridden was different.</p><form method="post"><input type="hidden" name="action" value="save_distances"><input type="hidden" name="event_id" value="<?php echo $eventId; ?>"><div class="row g-3"><?php foreach($classRows as $row): ?><div class="col-md-6"><label class="form-label fw-semibold"><?php echo h($row['group'].' — '.$row['label']); ?></label><input type="hidden" name="classes[<?php echo h($row['code']); ?>][label]" value="<?php echo h($row['label']); ?>"><input type="hidden" name="classes[<?php echo h($row['code']); ?>][group]" value="<?php echo h($row['group']); ?>"><div class="input-group"><input class="form-control" required min="0" max="999.99" step="0.01" type="number" name="classes[<?php echo h($row['code']); ?>][distance]" value="<?php echo h((string)$row['distance']); ?>"><span class="input-group-text">km</span></div></div><?php endforeach; ?></div><button class="btn btn-success mt-3">Save class distances</button></form></div>
<?php if($distancesReady): ?><div id="results" class="card-soft p-4"><div class="d-flex justify-content-between flex-wrap gap-2 mb-3"><div><h6 class="mb-1">2. Record competitor results</h6><p class="small text-muted mb-0">Select entries, apply a bulk status if useful, then save. Mileage eligibility is shown for reference and is saved with the result.</p></div><button form="results-form" class="btn btn-success">Save results</button></div><form method="post" id="results-form"><input type="hidden" name="action" value="save_results"><input type="hidden" name="event_id" value="<?php echo $eventId; ?>"><?php foreach(['PR','VPR','CTR','ER','OTHER'] as $group): $groupEntries=array_values(array_filter($entries,static fn($e)=>$e['class_group']===$group));if(!$groupEntries)continue; ?><section class="border rounded p-3 mb-4 result-section"><div class="d-flex flex-wrap align-items-center gap-2 mb-3"><h6 class="mb-0"><?php echo h($group); ?></h6><button type="button" class="btn btn-sm btn-outline-secondary" data-select="all">Select all</button><button type="button" class="btn btn-sm btn-outline-secondary" data-select="none">Select none</button><select class="form-select form-select-sm w-auto" data-bulk-status><option value="">Mark selected as…</option><?php foreach(['completed'=>'Completed','non_starter'=>'Non-starter','retired'=>'Retired','eliminated'=>'Eliminated','withdrawn'=>'Withdrawn','pending'=>'Pending'] as $value=>$label): ?><option value="<?php echo $value; ?>"><?php echo $label; ?></option><?php endforeach; ?></select><button type="button" class="btn btn-sm btn-outline-primary" data-apply-status>Apply</button></div><div class="table-responsive"><table class="table table-sm align-middle"><thead><tr><th></th><th>Rider / Horse</th><th>Class</th><th>Status</th><th>Distance</th><?php if($group!=='PR'): ?><th>Start</th><th>Finish</th><th>Ride time</th><th>Ready for vet</th><th>Vet time</th><th>Final HR</th><th>Pass / Fail</th><?php endif; ?><th>Notes</th></tr></thead><tbody><?php foreach($groupEntries as $entry): $id=(int)$entry['id'];$status=$entry['result_status']??'pending';$distance=$entry['distance_km']??($classRows[$entry['class_code']]['distance']??''); ?><tr data-result-row><td><input type="checkbox" class="form-check-input" data-row-select></td><td><strong><?php echo h($entry['rider_name']); ?></strong><div class="small text-muted"><?php echo h($entry['horse_name']); ?><?php echo $entry['member_eligible']?' · Member mileage':''; ?><?php echo $entry['logbook_eligible']?' · Logbook mileage':''; ?></div></td><td><?php echo h($entry['class_label']); ?></td><td><select class="form-select form-select-sm" name="results[<?php echo $id; ?>][status]" data-status><?php foreach(['pending'=>'Pending','completed'=>'Completed','non_starter'=>'Non-starter','retired'=>'Retired','eliminated'=>'Eliminated','withdrawn'=>'Withdrawn'] as $value=>$label): ?><option value="<?php echo $value; ?>" <?php echo $status===$value?'selected':''; ?>><?php echo $label; ?></option><?php endforeach; ?></select></td><td><div class="input-group input-group-sm"><input class="form-control" type="number" min="0" step="0.01" name="results[<?php echo $id; ?>][distance]" value="<?php echo h((string)$distance); ?>"><span class="input-group-text">km</span></div></td><?php if($group!=='PR'): $start=$entry['started_at']?date('H:i',strtotime($entry['started_at'])):'';$finish=$entry['finished_at']?date('H:i',strtotime($entry['finished_at'])):'';$vet=$entry['ready_for_vet_at']?date('H:i',strtotime($entry['ready_for_vet_at'])):''; ?><td><input class="form-control form-control-sm" type="time" name="results[<?php echo $id; ?>][start]" value="<?php echo h($start); ?>" data-start></td><td><input class="form-control form-control-sm" type="time" name="results[<?php echo $id; ?>][finish]" value="<?php echo h($finish); ?>" data-finish></td><td class="small text-nowrap" data-ride-time>—</td><td><input class="form-control form-control-sm" type="time" name="results[<?php echo $id; ?>][vet]" value="<?php echo h($vet); ?>" data-vet></td><td class="small text-nowrap" data-vet-time>—</td><td><input class="form-control form-control-sm" type="number" min="0" max="300" name="results[<?php echo $id; ?>][hr]" value="<?php echo h((string)($entry['final_heart_rate']??'')); ?>"></td><td><select class="form-select form-select-sm" name="results[<?php echo $id; ?>][vet_result]"><option value="">—</option><option value="pass" <?php echo ($entry['vet_result']??'')==='pass'?'selected':''; ?>>Pass</option><option value="fail" <?php echo ($entry['vet_result']??'')==='fail'?'selected':''; ?>>Fail</option></select></td><?php endif; ?><td><input class="form-control form-control-sm" name="results[<?php echo $id; ?>][notes]" value="<?php echo h((string)($entry['notes']??'')); ?>"></td></tr><?php endforeach; ?></tbody></table></div></section><?php endforeach; ?><button class="btn btn-success">Save results</button></form></div><?php else: ?><div class="alert alert-info">Save an actual distance for every entered class to unlock competitor results.</div><?php endif; ?>
<script>
document.querySelectorAll('.result-section').forEach(section=>{const rows=[...section.querySelectorAll('[data-result-row]')],set=checked=>rows.forEach(row=>row.querySelector('[data-row-select]').checked=checked);section.querySelector('[data-select="all"]').onclick=()=>set(true);section.querySelector('[data-select="none"]').onclick=()=>set(false);section.querySelector('[data-apply-status]').onclick=()=>{const value=section.querySelector('[data-bulk-status]').value;if(!value)return;rows.forEach(row=>{if(row.querySelector('[data-row-select]').checked)row.querySelector('[data-status]').value=value;});};const mins=(a,b)=>{if(!a||!b)return '—';const [ah,am]=a.split(':').map(Number),[bh,bm]=b.split(':').map(Number),n=bh*60+bm-ah*60-am;return n<0?'Check times':Math.floor(n/60)+'h '+String(n%60).padStart(2,'0')+'m'};const times=row=>{row.querySelector('[data-ride-time]')&&(row.querySelector('[data-ride-time]').textContent=mins(row.querySelector('[data-start]').value,row.querySelector('[data-finish]').value));row.querySelector('[data-vet-time]')&&(row.querySelector('[data-vet-time]').textContent=mins(row.querySelector('[data-finish]').value,row.querySelector('[data-vet]').value));};rows.forEach(row=>{times(row);row.querySelectorAll('input[type="time"]').forEach(input=>input.addEventListener('input',()=>times(row)));});});
</script>
<?php endif; admin_layout_end(); ?>
